package ly.com.tahaben.settings_portability

enum class SettingType { BOOLEAN, INT, LONG, FLOAT, DOUBLE, STRING, STRING_SET }

/**
 * One typed preference value. Int and Long are separate cases so a stored long never passes through a double
 * or an int (CLAIM(lossless-long)). A set compares as a set; its order is fixed only when written to a file.
 */
sealed interface SettingValue {
    val type: SettingType

    data class Bool(val value: Boolean) : SettingValue { override val type get() = SettingType.BOOLEAN }
    data class Int32(val value: Int) : SettingValue { override val type get() = SettingType.INT }
    data class Int64(val value: Long) : SettingValue { override val type get() = SettingType.LONG }
    data class Float32(val value: Float) : SettingValue { override val type get() = SettingType.FLOAT }
    data class Float64(val value: Double) : SettingValue { override val type get() = SettingType.DOUBLE }
    data class Text(val value: String) : SettingValue { override val type get() = SettingType.STRING }
    data class TextSet(val values: Set<String>) : SettingValue { override val type get() = SettingType.STRING_SET }
}
package ly.com.tahaben.settings_portability

/** The two key-value stores that hold settings. Room configuration rows are separate ([ConfigurationRows]). */
enum class SettingsStoreId { SHARED_PREFERENCES, DATA_STORE }

/** Row of `apps_db`: a launcher activity. [userSerial] is only meaningful on the same device and user. */
data class AppActivityRow(
    val appName: String,
    val packageName: String,
    val activityName: String,
    val userSerial: Long,
)

/** Row of `TimeLimitEntity`. */
data class TimeLimitRow(
    val packageName: String,
    val timeLimitInMilli: Long,
    val timeAtAddingInMilli: Long,
)

/** Every configuration row. These two tables are the only SQL tables that hold settings. */
data class ConfigurationRows(
    val apps: List<AppActivityRow> = emptyList(),
    val timeLimits: List<TimeLimitRow> = emptyList(),
)

/** The complete configuration across all three stores: what an export holds and what an import replaces. */
data class SettingsConfiguration(
    val sharedPreferences: Map<String, SettingValue> = emptyMap(),
    val dataStore: Map<String, SettingValue> = emptyMap(),
    val rows: ConfigurationRows = ConfigurationRows(),
)

/** Where the settings came from. Informational; never used to decide what to apply. */
data class PortableSource(
    val packageName: String,
    val versionName: String,
    val versionCode: Long,
    val userId: Int,
)

/** A key found in the source that the catalog does not know. Name only: its value is never carried. */
data class UnsupportedKey(val store: SettingsStoreId, val key: String)

data class PortableSettings(
    val source: PortableSource,
    val configuration: SettingsConfiguration,
    val unsupportedKeys: List<UnsupportedKey> = emptyList(),
)

enum class ExclusionReason { SECRET, INTERNAL, HISTORY }

/** A key the catalog deliberately leaves out. Name only, for the preview. */
data class OmittedSetting(val store: SettingsStoreId, val key: String, val reason: ExclusionReason)

data class ConversionReport(val omitted: Set<OmittedSetting>)

enum class PortableSettingsErrorCode {
    MALFORMED_JSON,
    MALFORMED_XML,
    TOO_LARGE,
    TOO_MANY_ENTRIES,
    TOO_DEEP,
    WRONG_FORMAT,
    UNSUPPORTED_VERSION,
    DUPLICATE_KEY,
    TYPE_MISMATCH,
    OUT_OF_RANGE,
    EXCLUDED_KEY,
    UNSUPPORTED_KEY,
    SEMANTIC_REJECTED,
}

/** [location] names a store and key (for example `sharedPreferences/notification_flood_threshold`). Never a value. */
data class PortableSettingsError(val code: PortableSettingsErrorCode, val location: String)

sealed interface PortableSettingsResult {
    data class Ready(val settings: PortableSettings, val report: ConversionReport) : PortableSettingsResult
    data class Failed(val error: PortableSettingsError) : PortableSettingsResult
}
package ly.com.tahaben.settings_portability

/**
 * Checks meaning the pure module cannot know: schedule JSON, enum names and similar. The Android side
 * implements it with the existing ScheduleCodec and domain enums. Returns the first problem, or null.
 */
fun interface SemanticValidator {
    fun firstProblem(configuration: SettingsConfiguration): SemanticProblem?
}

/** Names the setting only. Never carries its value. */
data class SemanticProblem(val store: SettingsStoreId, val key: String)

/** What the rescue helper reads out of the copied source: raw files plus the already-decoded typed stores. */
data class LegacySourceSnapshot(
    val source: PortableSource,
    /** Raw `shared_prefs/shared_pref.xml`. */
    val sharedPreferencesXml: String,
    /** DataStore decoded through the public DataStore API by an adapter; not protobuf bytes. */
    val dataStore: Map<String, SettingValue>,
    /** Result of selecting only the configuration rows from the copied database. */
    val rows: ConfigurationRows,
)

/**
 * Old app files -> portable settings. Parses legacy SharedPreferences XML strictly and applies [SettingsCatalog].
 *
 * Invariants:
 *  - CLAIM(catalog-only): only catalog Configuration keys reach the output. Excluded and import-reset keys are
 *    named in the report; unknown keys are named in unsupportedKeys; neither value is carried.
 *  - CLAIM(types-kept): each value keeps its original type (long stays long, set stays set).
 *  - CLAIM(no-silent-default): XML defects, a duplicate name, a type that disagrees with the catalog, an
 *    unknown element, or a semantic problem yield Failed. Nothing is replaced with a default.
 *  - CLAIM(xml-no-doctype): a document type declaration is refused before any entity is read, whether or not the
 *    platform parser supports the external-entity feature flags (see [LegacyXml]).
 *  - The result is checked like an export ([ConfigurationChecks.saveProblem]), so a conversion never yields a
 *    file that stage would refuse.
 *  - Schedule JSON and legacy schedule keys are kept verbatim. The app's own lazy migration (ScheduleCodec and
 *    DaySchedule.repairLegacy on first read) upgrades them; [SemanticValidator] rejects an undecodable one now.
 */
object LegacySettingsConverter {
    fun convert(
        snapshot: LegacySourceSnapshot,
        validator: SemanticValidator,
        limits: DecodeLimits = DecodeLimits(),
    ): PortableSettingsResult {
        val sharedValues = when (val parsed = LegacyXml.parse(snapshot.sharedPreferencesXml, limits)) {
            is LegacyXml.Parsed.Values -> parsed.values
            is LegacyXml.Parsed.Failure -> return PortableSettingsResult.Failed(parsed.error)
        }
        val shared = when (val outgoing = ConfigurationChecks.classifyOutgoing(SettingsStoreId.SHARED_PREFERENCES, sharedValues)) {
            is ConfigurationChecks.Outgoing.Done -> outgoing.classified
            is ConfigurationChecks.Outgoing.Refused -> return PortableSettingsResult.Failed(outgoing.error)
        }
        val dataStore = when (val outgoing = ConfigurationChecks.classifyOutgoing(SettingsStoreId.DATA_STORE, snapshot.dataStore)) {
            is ConfigurationChecks.Outgoing.Done -> outgoing.classified
            is ConfigurationChecks.Outgoing.Refused -> return PortableSettingsResult.Failed(outgoing.error)
        }
        val configuration = SettingsConfiguration(shared.configuration, dataStore.configuration, ConfigurationChecks.canonical(snapshot.rows))
        val settings = PortableSettings(
            snapshot.source,
            configuration,
            ConfigurationChecks.canonical(shared.unsupported + dataStore.unsupported),
        )
        ConfigurationChecks.semanticProblem(validator, configuration)?.let { return PortableSettingsResult.Failed(it) }
        ConfigurationChecks.saveProblem(settings, limits)?.let { return PortableSettingsResult.Failed(it) }
        return PortableSettingsResult.Ready(settings, ConversionReport(shared.omitted + dataStore.omitted))
    }
}
package ly.com.tahaben.settings_portability

/**
 * A key-value store (SharedPreferences or DataStore) as the importer sees it. Adapters stay dumb: the shared
 * code decides which keys belong to the configuration domain, via [SettingsCatalog].
 */
interface PreferencesStore {
    /** Every key in the store, settings and internals alike. */
    fun readAll(): Map<String, SettingValue>

    /**
     * Removes [removeKeys] and writes [put] as one atomic, durable commit. Idempotent. Throws on failure.
     * Must not touch any other key.
     */
    fun apply(removeKeys: Set<String>, put: Map<String, SettingValue>)
}

/** The configuration rows (`apps_db`, `TimeLimitEntity`). Never the history tables. */
interface ConfigurationRowsStore {
    fun read(): ConfigurationRows

    /** Replaces both tables in one transaction. Idempotent. Throws on failure, leaving the old rows. */
    fun replace(rows: ConfigurationRows)
}

/** The smallest SQL surface the shared code needs. Android adapters wrap SQLiteDatabase; tests wrap JDBC. */
interface SqlSession {
    /** Each row is a list of Long, String or null in select-list order. */
    fun query(sql: String, args: List<Any?> = emptyList()): List<List<Any?>>
    fun execute(sql: String, args: List<Any?> = emptyList())
}

interface SqlTransactionRunner {
    /** Commits when [block] returns, rolls back when it throws. */
    fun <T> inTransaction(block: (SqlSession) -> T): T
}

/**
 * [ConfigurationRowsStore] over SQL. Touches only `apps_db` and `TimeLimitEntity`.
 *
 * CLAIM(config-sql-only): no statement names any other table, so history survives a replace [SqlConfigurationRowsStoreTest].
 * CLAIM(rows-atomic): delete and insert commit together or not at all [SqlConfigurationRowsStoreTest].
 *
 * Reads are ordered by primary key so the result does not depend on rowid order. A column that is not the
 * expected Long or String throws [IllegalStateException]: the store never coerces or defaults a value.
 */
class SqlConfigurationRowsStore(private val runner: SqlTransactionRunner) : ConfigurationRowsStore {
    override fun read(): ConfigurationRows = runner.inTransaction { session ->
        ConfigurationRows(
            apps = session.query(
                "SELECT `app_name`, `package_name`, `activity_name`, `user_serial` FROM `apps_db` ORDER BY `app_name`, `package_name`",
            ).map { AppActivityRow(text(it, 0), text(it, 1), text(it, 2), long(it, 3)) },
            timeLimits = session.query(
                "SELECT `packageName`, `timeLimitInMilli`, `timeAtAddingInMilli` FROM `TimeLimitEntity` ORDER BY `packageName`",
            ).map { TimeLimitRow(text(it, 0), long(it, 1), long(it, 2)) },
        )
    }

    override fun replace(rows: ConfigurationRows) = runner.inTransaction { session ->
        session.execute("DELETE FROM `apps_db`")
        session.execute("DELETE FROM `TimeLimitEntity`")
        for (row in rows.apps) {
            session.execute(
                "INSERT INTO `apps_db` (`app_name`, `package_name`, `activity_name`, `user_serial`) VALUES (?, ?, ?, ?)",
                listOf(row.appName, row.packageName, row.activityName, row.userSerial),
            )
        }
        for (row in rows.timeLimits) {
            session.execute(
                "INSERT INTO `TimeLimitEntity` (`packageName`, `timeLimitInMilli`, `timeAtAddingInMilli`) VALUES (?, ?, ?)",
                listOf(row.packageName, row.timeLimitInMilli, row.timeAtAddingInMilli),
            )
        }
    }

    private fun text(row: List<Any?>, column: Int): String =
        row[column] as? String ?: throw IllegalStateException("configuration column $column is not text")

    private fun long(row: List<Any?>, column: Int): Long =
        row[column] as? Long ?: throw IllegalStateException("configuration column $column is not an integer")
}

