class Faults {
    var operations = 0
        private set
    var crashAtOperation: Int? = null
    var tearOnCrash = false

    fun beforeMutation(tear: () -> Unit) {
        operations++
        if (crashAtOperation == operations) {
            if (tearOnCrash) tear()
